document.querySelectorAll('.ipd').forEach(root => {
  const trigger = root.querySelector('.ipd__t'), menu = root.querySelector('.ipd__m');
  const items = () => [...menu.querySelectorAll('[role=menuitem]')];
  const close = refocus => { menu.hidden = true; trigger.setAttribute('aria-expanded', 'false'); if (refocus) trigger.focus(); };
  const open = last => { menu.hidden = false; trigger.setAttribute('aria-expanded', 'true'); const l = items(); (last ? l[l.length - 1] : l[0]).focus(); };
  trigger.addEventListener('click', () => menu.hidden ? open() : close(true));
  trigger.addEventListener('keydown', e => { if (e.key === 'ArrowDown') { e.preventDefault(); open(); } else if (e.key === 'ArrowUp') { e.preventDefault(); open(true); } });
  menu.addEventListener('keydown', e => {
    const l = items(), i = l.indexOf(document.activeElement);
    const to = { ArrowDown: (i + 1) % l.length, ArrowUp: (i - 1 + l.length) % l.length, Home: 0, End: l.length - 1 }[e.key];
    if (to !== undefined) { e.preventDefault(); l[to].focus(); } else if (e.key === 'Escape') { e.preventDefault(); close(true); } else if (e.key === 'Tab') close(false);
  });
  menu.addEventListener('click', e => { if (e.target.closest('[role=menuitem]')) close(true); });
  document.addEventListener('click', e => { if (!root.contains(e.target)) close(false); });
});
